package galera

import (
	"bytes"
	"fmt"
	"text/template"

	mariadbv1alpha1 "github.com/mariadb-operator/mariadb-operator/api/v1alpha1"
	"github.com/mariadb-operator/mariadb-operator/pkg/builder"
	mdbembed "github.com/mariadb-operator/mariadb-operator/pkg/embed"
	"k8s.io/apimachinery/pkg/types"
)

var galeraInitConfigMapDataTmpl = template.Must(template.New("init").Parse(`
#!/bin/bash

set -eo pipefail

CURDIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

source "${CURDIR}/lib.sh"

run_as_mysql() {
	if [ "$(id -u)" = "0" ]; then
		mysql_note "Running as root, will run script as mysql user"
		su - mysql -s /bin/bash -c "$@"
	else
		mysql_note "Running as non-root user"
		"$@"
	fi
}

mysql_note "Starting Galera init script"
mysql_check_config
docker_setup_env
docker_create_db_directories

if [ -z "$(ls -A /var/lib/mysql)" ]; then
	mysql_note "Initializing database"
	run_as_mysql docker_mariadb_init
else
	mysql_note "Database already initialized"
	mysql_note "Starting temporary server"
	run_as_mysql docker_mariadb_up --skip-networking --socket="/var/run/mysqld/mysqld.sock"
	mysql_note "Checking if root password is set"
	if run_as_mysql docker_mariadb_check_root_password; then
		mysql_note "Root password is set"
	else
		mysql_note "Root password is not set"
	fi
	mysql_note "Stopping temporary server"
	run_as_mysql docker_mariadb_stop
fi
`))

// galeraInitConfigMapKey defines the key for the Galera init ConfigMap.
func galeraInitConfigMapKey(mdb *mariadbv1alpha1.MariaDB) types.NamespacedName {
	return types.NamespacedName{
		Name:      fmt.Sprintf("%s-init", mdb.Name),
		Namespace: mdb.Namespace,
	}
}

// galeraInitConfigMapData returns the data for the Galera init ConfigMap: an
// init script that sources the embedded mariadb-docker entrypoint as a library
// and performs the database initialization, as well as the raw embedded
// entrypoint stored in the 'lib.sh' key.
func galeraInitConfigMapData() (map[string]string, error) {
	entrypoint, err := mdbembed.ReadEntrypoint()
	if err != nil {
		return nil, fmt.Errorf("error reading embedded entrypoint: %v", err)
	}

	var initScript bytes.Buffer
	if err := galeraInitConfigMapDataTmpl.Execute(&initScript, nil); err != nil {
		return nil, fmt.Errorf("error rendering init script: %v", err)
	}

	return map[string]string{
		builder.InitEntrypointKey: initScript.String(),
		builder.InitLibKey:        string(entrypoint),
	}, nil
}

