	var sts appsv1.StatefulSet
	if err := r.Get(ctx, client.ObjectKeyFromObject(mariadb), &sts); err != nil {
		return nil, err
	}
	return &sts, nil
}

func (r *GaleraReconciler) reconcileConfigMaps(ctx context.Context, mariadb *mariadbv1alpha1.MariaDB) error {
	data, err := galeraInitConfigMapData()
	if err != nil {
		return fmt.Errorf("error building Galera init ConfigMap data: %v", err)
	}
	req := &configmap.ReconcileRequest{
		Mariadb: mariadb,
		Owner:   mariadb,
		Key:     galeraInitConfigMapKey(mariadb),
		Data:    data,
	}
	return r.configMapReconciler.Reconcile(ctx, req)
}

