func TestGaleraInitConfigMapDataTemp(t *testing.T) {
	entrypoint, err := mdbembed.ReadEntrypoint()
	if err != nil {
		t.Fatalf("error reading entrypoint: %v", err)
	}
	for _, expected := range []string{"docker_mariadb_init", "docker_setup_env", "mysql_note", "mysql_check_config", "docker_create_db_directories"} {
		if !strings.Contains(string(entrypoint), expected) {
			t.Errorf("embedded entrypoint doesn't contain %q", expected)
		}
	}

	data, err := galeraInitConfigMapData()
	if err != nil {
		t.Fatalf("error building configmap data: %v", err)
	}
	if _, ok := data[builder.InitEntrypointKey]; !ok {
		t.Errorf("missing %q key", builder.InitEntrypointKey)
	}
	if _, ok := data[builder.InitLibKey]; !ok {
		t.Errorf("missing %q key", builder.InitLibKey)
	}
	script := data[builder.InitEntrypointKey]
	if !strings.Contains(script, `source "${CURDIR}/lib.sh"`) {
		t.Errorf("init script doesn't source lib.sh: %v", script)
	}
}

