Generic key-value option:
```go
package config

import (
	"fmt"
	"strings"
)

// KVOption is a generic key-value option.
type KVOption struct {
	Key   string
	Value string
}

func NewKVOption(key, value string) KVOption {
	return KVOption{Key: key, Value: value}
}

func (o KVOption) Marshal() (string, error) {
	if o.Key == "" {
		return "", fmt.Errorf("key must not be empty")
	}
	return fmt.Sprintf("%s=%s", o.Key, o.Value), nil
}

func (o *KVOption) Unmarshal(s string) error {
	key, value, err := splitKeyValue(s)
	if err != nil {
		return err
	}
	o.Key = key
	o.Value = value
	return nil
}

func splitKeyValue(s string) (string, string, error) {
	idx := strings.Index(s, "=")
	if idx < 0 || idx == 0 {
		return "", "", fmt.Errorf("invalid key-value option: %q", s)
	}
	return s[:idx], s[idx+1:], nil
}
```

#### provider.go
```go
package config

import (
	"fmt"
	"sort"
	"strings"
)

// ProviderOptions represents the wsrep_provider_options Galera configuration variable, which is a
// semicolon-separated list of 'key=value' options.
type ProviderOptions struct {
	opts map[string]string
}

func NewProviderOptions() *ProviderOptions {
	return &ProviderOptions{opts: make(map[string]string)}
}

func (o *ProviderOptions) Options() map[string]string {
	return o.opts
}

func (o *ProviderOptions) Set(key, value string) {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	o.opts[key] = value
}

func (o *ProviderOptions) Get(key string) (string, bool) {
	if o.opts == nil {
		return "", false
	}
	value, ok := o.opts[key]
	return value, ok
}

func (o *ProviderOptions) Delete(key string) {
	if o.opts == nil {
		return
	}
	delete(o.opts, key)
}

func (o *ProviderOptions) Has(key string) bool {
	if o.opts == nil {
		return false
	}
	_, ok := o.opts[key]
	return ok
}

func (o *ProviderOptions) Len() int {
	if o.opts == nil {
		return 0
	}
	return len(o.opts)
}

// Update updates the ProviderOptions with the given options. If the value is empty the option is removed.
func (o *ProviderOptions) Update(opts ...KVOption) {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	for _, opt := range opts {
		if opt.Value == "" {
			delete(o.opts, opt.Key)
		} else {
			o.opts[opt.Key] = opt.Value
		}
	}
}

// Marshal serializes the ProviderOptions into a semicolon-separated string of 'key=value' options.
func (o *ProviderOptions) Marshal() (string, error) {
	if o.opts == nil || len(o.opts) == 0 {
		return "", nil
	}
	keys := make([]string, 0, len(o.opts))
	for k := range o.opts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var parts []string
	for _, k := range keys {
		kv := KVOption{Key: k, Value: o.opts[k]}
		s, err := kv.Marshal()
		if err != nil {
			return "", err
		}
		parts = append(parts, s)
	}
	return strings.Join(parts, ";"), nil
}

// Unmarshal parses a semicolon-separated string of 'key=value' options into the ProviderOptions.
func (o *ProviderOptions) Unmarshal(s string) error {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	if strings.TrimSpace(s) == "" {
		return nil
	}
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		var kv KVOption
		if err := kv.Unmarshal(part); err != nil {
			return err
		}
		o.opts[kv.Key] = kv.Value
	}
	return nil
}
```

