// IsIPv6Address indicates whether the given IP address is an IPv6 address.
func IsIPv6Address(address string) bool {
	ip := net.ParseIP(strings.TrimPrefix(strings.TrimSuffix(address, "]"), "["))
	return ip != nil && ip.To4() == nil
}

// FormatAddress formats an IP address to be used in a 'host:port' format, adding brackets for IPv6.
func FormatAddress(address string, port int32) string {
	if IsIPv6Address(address) {
		return fmt.Sprintf("[%s]:%d", address, port)
	}
	return fmt.Sprintf("%s:%d", address, port)
}
