// Package keys centralizes the keys used in the Galera configuration files and in the
// wsrep_provider_options Galera configuration variable.
package keys

const (
	// Galera configuration keys used in the MariaDB Galera configuration file.
	WsrepOn                = "wsrep_on"
	WsrepProvider          = "wsrep_provider"
	WsrepProviderOptions   = "wsrep_provider_options"
	WsrepClusterName       = "wsrep_cluster_name"
	WsrepClusterAddress    = "wsrep_cluster_address"
	WsrepNodeAddress       = "wsrep_node_address"
	WsrepNodeName          = "wsrep_node_name"
	WsrepSstMethod         = "wsrep_sst_method"
	WsrepSstReceiveAddress = "wsrep_sst_receive_address"
	WsrepSlaveThreads      = "wsrep_slave_threads"

	// wsrep_provider_options keys managed by the operator.
	IstRecvAddr     = "ist.recv_addr"
	GmcastListenAddr = "gmcast.listen_addr"
)

// ReservedProviderOptions are the wsrep_provider_options keys that are configured by the operator
// and therefore cannot be overridden by the user.
var ReservedProviderOptions = []string{
	IstRecvAddr,
	GmcastListenAddr,
}

package config

import (
	"fmt"
	"strings"
)

// KVOption is a generic key-value option.
type KVOption struct {
	Key   string
	Value string
}

// NewKVOption returns a KVOption given a key and a value.
func NewKVOption(key, value string) KVOption {
	return KVOption{
		Key:   key,
		Value: value,
	}
}

// Marshal serializes the KVOption into a 'key=value' string.
func (o *KVOption) Marshal() (string, error) {
	if o.Key == "" {
		return "", fmt.Errorf("key must not be empty")
	}
	return fmt.Sprintf("%s=%s", o.Key, o.Value), nil
}

// Unmarshal parses a 'key=value' string into the KVOption.
func (o *KVOption) Unmarshal(s string) error {
	key, value, err := splitKVOption(s)
	if err != nil {
		return err
	}
	o.Key = key
	o.Value = value
	return nil
}

func splitKVOption(s string) (string, string, error) {
	idx := strings.Index(s, "=")
	if idx <= 0 {
		return "", "", fmt.Errorf("invalid key-value option '%s'", s)
	}
	return s[:idx], s[idx+1:], nil
}

package config

import (
	"fmt"
	"sort"
	"strings"
)

// ProviderOptions represents the wsrep_provider_options Galera configuration variable, which is a
// semicolon-separated list of 'key=value' options.
type ProviderOptions struct {
	opts map[string]string
}

// NewProviderOptions returns an empty ProviderOptions.
func NewProviderOptions() *ProviderOptions {
	return &ProviderOptions{
		opts: make(map[string]string),
	}
}

// Options returns the underlying map of options.
func (o *ProviderOptions) Options() map[string]string {
	return o.opts
}

// Set sets an option given a key and a value.
func (o *ProviderOptions) Set(key, value string) {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	o.opts[key] = value
}

// Get returns the value of an option given a key, indicating whether it was found.
func (o *ProviderOptions) Get(key string) (string, bool) {
	if o.opts == nil {
		return "", false
	}
	value, ok := o.opts[key]
	return value, ok
}

// Delete removes an option given a key.
func (o *ProviderOptions) Delete(key string) {
	if o.opts == nil {
		return
	}
	delete(o.opts, key)
}

// Has indicates whether an option exists given a key.
func (o *ProviderOptions) Has(key string) bool {
	if o.opts == nil {
		return false
	}
	_, ok := o.opts[key]
	return ok
}

// Update updates the ProviderOptions with the given options. If an option value is empty, the
// option is removed from the ProviderOptions.
func (o *ProviderOptions) Update(opts ...KVOption) {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	for _, opt := range opts {
		if opt.Value == "" {
			delete(o.opts, opt.Key)
		} else {
			o.opts[opt.Key] = opt.Value
		}
	}
}

// Marshal serializes the ProviderOptions into a semicolon-separated string of 'key=value' options.
func (o *ProviderOptions) Marshal() (string, error) {
	if o.opts == nil || len(o.opts) == 0 {
		return "", nil
	}
	keys := make([]string, 0, len(o.opts))
	for k := range o.opts {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		kv := KVOption{
			Key:   k,
			Value: o.opts[k],
		}
		part, err := (&kv).Marshal()
		if err != nil {
			return "", fmt.Errorf("error serializing option '%s': %v", k, err)
		}
		parts = append(parts, part)
	}
	return strings.Join(parts, ";"), nil
}

// Unmarshal parses a semicolon-separated string of 'key=value' options into the ProviderOptions.
func (o *ProviderOptions) Unmarshal(s string) error {
	if o.opts == nil {
		o.opts = make(map[string]string)
	}
	if strings.TrimSpace(s) == "" {
		return nil
	}
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		var kv KVOption
		if err := (&kv).Unmarshal(part); err != nil {
			return err
		}
		o.opts[kv.Key] = kv.Value
	}
	return nil
}

package config

import (
	"fmt"
	"net"
	"strings"

	galeraresources "github.com/mariadb-operator/mariadb-operator/pkg/controller/galera/resources"
	"github.com/mariadb-operator/mariadb-operator/pkg/galera/config/keys"
)

const (
	// DefaultProviderPath is the default path to the Galera wsrep provider library.
	DefaultProviderPath = "/usr/lib/galera/libgalera_smm.so"
	// GaleraEnabled indicates that wsrep is enabled.
	GaleraEnabled = "ON"
)

// GaleraConfig is the Galera configuration for a single node of a Galera cluster.
type GaleraConfig struct {
	ClusterName     string
	ClusterAddress  string
	NodeName        string
	NodeAddress     string
	SstMethod       string
	ReplicaThreads  int
	ProviderOptions *ProviderOptions
}

// IsIPv6Address indicates whether the given address is an IPv6 address.
func IsIPv6Address(address string) bool {
	ip := net.ParseIP(strings.Trim(address, "[]"))
	return ip != nil && ip.To4() == nil
}

// FormatAddress formats an address and a port into an 'address:port' notation, adding brackets to
// IPv6 addresses.
func FormatAddress(address string, port int32) string {
	address = strings.Trim(address, "[]")
	if IsIPv6Address(address) {
		return fmt.Sprintf("[%s]:%d", address, port)
	}
	return fmt.Sprintf("%s:%d", address, port)
}

// SstReceiveAddress derives the wsrep_sst_receive_address for the given node address, which is used
// to configure the address the node receives the Snapshot State Transfer on.
func SstReceiveAddress(nodeAddress string) string {
	return FormatAddress(nodeAddress, galeraresources.GaleraSSTPort)
}

// NodeProviderOptions derives the wsrep_provider_options that are managed by the operator for the
// given node address: the 'ist.recv_addr' option is always set to the node address, while the
// 'gmcast.listen_addr' option is only set for IPv6 nodes, as Galera is not able to auto detect the
// listening address in IPv6 environments.
func NodeProviderOptions(nodeAddress string) KVOption {
	opts := []KVOption{
		NewKVOption(keys.IstRecvAddr, FormatAddress(nodeAddress, galeraresources.GaleraISTPort)),
	}
	if IsIPv6Address(nodeAddress) {
		opts = append(opts, NewKVOption(keys.GmcastListenAddr,
			fmt.Sprintf("tcp://%s", FormatAddress(nodeAddress, galeraresources.GaleraClusterPort))))
	}
	return NewKVOption(strings.Join([]string{}, ""), "")
}

// providerOptionsForNode returns the ProviderOptions subset managed by the operator for the given
// node address.
func providerOptionsForNode(nodeAddress string) *ProviderOptions {
	opts := NewProviderOptions()
	opts.Set(keys.IstRecvAddr, FormatAddress(nodeAddress, galeraresources.GaleraISTPort))
	if IsIPv6Address(nodeAddress) {
		opts.Set(keys.GmcastListenAddr,
			fmt.Sprintf("tcp://%s", FormatAddress(nodeAddress, galeraresources.GaleraClusterPort)))
	}
	return opts
}

// Marshal renders the GaleraConfig into the content of a MariaDB Galera configuration file.
func (g *GaleraConfig) Marshal() (string, error) {
	providerOpts := NewProviderOptions()
	if g.ProviderOptions != nil {
		for key, value := range g.ProviderOptions.Options() {
			providerOpts.Set(key, value)
		}
	}
	for key, value := range providerOptionsForNode(g.NodeAddress).Options() {
		providerOpts.Set(key, value)
	}
	providerOptionsStr, err := providerOpts.Marshal()
	if err != nil {
		return "", fmt.Errorf("error serializing provider options: %v", err)
	}

	var sb strings.Builder
	sb.WriteString("[mariadb]\n")
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepOn, GaleraEnabled))
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepProvider, DefaultProviderPath))
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepClusterName, g.ClusterName))
	if g.ClusterAddress != "" {
		sb.WriteString(fmt.Sprintf("%s=gcomm://%s\n", keys.WsrepClusterAddress, g.ClusterAddress))
	}
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepNodeName, g.NodeName))
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepNodeAddress, g.NodeAddress))
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepSstMethod, g.SstMethod))
	sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepSstReceiveAddress, SstReceiveAddress(g.NodeAddress)))
	sb.WriteString(fmt.Sprintf("%s=%d\n", keys.WsrepSlaveThreads, g.ReplicaThreads))
	if providerOptionsStr != "" {
		sb.WriteString(fmt.Sprintf("%s=%s\n", keys.WsrepProviderOptions, providerOptionsStr))
	}
	return sb.String(), nil
}

