package config

import (
	"fmt"
	"os"
	"strings"

	"github.com/mariadb-operator/mariadb-operator/pkg/galera/config/keys"
)

// UpdateConfig updates the node-related keys (node address, SST receive address and provider
// options) in the existing Galera configuration file located at configFile, based on the given node
// address. Non node-related settings, such as user provided provider options, are preserved.
func UpdateConfig(configFile, nodeAddress string) error {
	content, err := os.ReadFile(configFile)
	if err != nil {
		return fmt.Errorf("error reading config file '%s': %v", configFile, err)
	}

	providerOptions := NewProviderOptions()
	if err := providerOptions.Unmarshal(getConfigValue(string(content), keys.WsrepProviderOptions)); err != nil {
		return fmt.Errorf("error parsing provider options: %v", err)
	}
	providerOptions.Update(NewKVOption(keys.GmcastListenAddr, ""))
	for key, value := range providerOptionsForNode(nodeAddress).Options() {
		providerOptions.Update(NewKVOption(key, value))
	}
	providerOptionsStr, err := providerOptions.Marshal()
	if err != nil {
		return fmt.Errorf("error serializing provider options: %v", err)
	}

	config := setConfigValue(string(content), keys.WsrepNodeAddress, nodeAddress)
	config = setConfigValue(config, keys.WsrepSstReceiveAddress, SstReceiveAddress(nodeAddress))
	config = setConfigValue(config, keys.WsrepProviderOptions, providerOptionsStr)

	if err := os.WriteFile(configFile, []byte(config), 0644); err != nil {
		return fmt.Errorf("error writing config file '%s': %v", configFile, err)
	}
	return nil
}

func getConfigValue(content, key string) string {
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, key+"=") {
			return strings.TrimPrefix(line, key+"=")
		}
	}
	return ""
}

func setConfigValue(content, key, value string) string {
	var updated []string
	found := false
	for _, line := range strings.Split(content, "\n") {
		if strings.HasPrefix(strings.TrimSpace(line), key+"=") {
			updated = append(updated, fmt.Sprintf("%s=%s", key, value))
			found = true
		} else {
			updated = append(updated, line)
		}
	}
	if !found {
		updated = append(updated, fmt.Sprintf("%s=%s", key, value))
	}
	return strings.Join(updated, "\n")
}

