package config

import (
	"testing"
)

func TestKVOptionMarshal(t *testing.T) {
	tests := []struct {
		name    string
		opt     KVOption
		want    string
		wantErr bool
	}{
		{
			name: "with key and value",
			opt:  NewKVOption("gcs.fc_limit", "64"),
			want: "gcs.fc_limit=64",
		},
		{
			name: "with empty value",
			opt:  NewKVOption("ist.recv_addr", ""),
			want: "ist.recv_addr=",
		},
		{
			name:    "with empty key",
			opt:     NewKVOption("", "foo"),
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := (&tt.opt).Marshal()
			if tt.wantErr {
				if err == nil {
					t.Fatalf("expecting error, got none")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tt.want {
				t.Errorf("expecting %q, got %q", tt.want, got)
			}
		})
	}
}

func TestKVOptionUnmarshal(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    KVOption
		wantErr bool
	}{
		{
			name:  "with key and value",
			input: "gcs.fc_limit=64",
			want:  NewKVOption("gcs.fc_limit", "64"),
		},
		{
			name:  "with empty value",
			input: "ist.recv_addr=",
			want:  NewKVOption("ist.recv_addr", ""),
		},
		{
			name:  "with '=' in value",
			input: "evs.keepalive_period=PT0.5S",
			want:  NewKVOption("evs.keepalive_period", "PT0.5S"),
		},
		{
			name:    "without separator",
			input:   "gcs.fc_limit",
			wantErr: true,
		},
		{
			name:    "with empty key",
			input:   "=foo",
			wantErr: true,
		},
		{
			name:    "with empty input",
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var opt KVOption
			err := (&opt).Unmarshal(tt.input)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("expecting error, got none")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if opt != tt.want {
				t.Errorf("expecting %+v, got %+v", tt.want, opt)
			}
		})
	}
}

package config

import (
	"testing"
)

func TestProviderOptionsSetGetHasDelete(t *testing.T) {
	opts := NewProviderOptions()

	if opts.Has("gcs.fc_limit") {
		t.Errorf("unexpected option found")
	}
	opts.Set("gcs.fc_limit", "64")
	if !opts.Has("gcs.fc_limit") {
		t.Errorf("expecting option to be present")
	}
	value, ok := opts.Get("gcs.fc_limit")
	if !ok || value != "64" {
		t.Errorf("expecting value %q, got %q (found: %t)", "64", value, ok)
	}
	opts.Delete("gcs.fc_limit")
	if opts.Has("gcs.fc_limit") {
		t.Errorf("expecting option to be removed")
	}
}

func TestProviderOptionsUpdate(t *testing.T) {
	opts := NewProviderOptions()
	opts.Update(
		NewKVOption("gcs.fc_limit", "64"),
		NewKVOption("gcs.fc_factor", "0.8"),
	)
	if value, _ := opts.Get("gcs.fc_limit"); value != "64" {
		t.Errorf("expecting gcs.fc_limit to be %q, got %q", "64", value)
	}
	if value, _ := opts.Get("gcs.fc_factor"); value != "0.8" {
		t.Errorf("expecting gcs.fc_factor to be %q, got %q", "0.8", value)
	}

	opts.Update(NewKVOption("gcs.fc_factor", ""))
	if opts.Has("gcs.fc_factor") {
		t.Errorf("expecting gcs.fc_factor to be removed")
	}
	if !opts.Has("gcs.fc_limit") {
		t.Errorf("expecting gcs.fc_limit to be preserved")
	}
}

func TestProviderOptionsMarshal(t *testing.T) {
	opts := NewProviderOptions()
	opts.Set("gcs.fc_limit", "64")
	opts.Set("evs.keepalive_period", "PT1S")

	got, err := opts.Marshal()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := "evs.keepalive_period=PT1S;gcs.fc_limit=64"
	if got != want {
		t.Errorf("expecting %q, got %q", want, got)
	}
}

func TestProviderOptionsMarshalEmpty(t *testing.T) {
	opts := NewProviderOptions()
	got, err := opts.Marshal()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "" {
		t.Errorf("expecting empty string, got %q", got)
	}
}

func TestProviderOptionsUnmarshal(t *testing.T) {
	opts := NewProviderOptions()
	if err := opts.Unmarshal("gcs.fc_limit=64;evs.keepalive_period=PT1S;ist.recv_addr=10.0.0.1:4568"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if value, _ := opts.Get("gcs.fc_limit"); value != "64" {
		t.Errorf("expecting gcs.fc_limit to be %q, got %q", "64", value)
	}
	if value, _ := opts.Get("evs.keepalive_period"); value != "PT1S" {
		t.Errorf("expecting evs.keepalive_period to be %q, got %q", "PT1S", value)
	}
	if value, _ := opts.Get("ist.recv_addr"); value != "10.0.0.1:4568" {
		t.Errorf("expecting ist.recv_addr to be %q, got %q", "10.0.0.1:4568", value)
	}
}

func TestProviderOptionsUnmarshalEmpty(t *testing.T) {
	opts := NewProviderOptions()
	if err := opts.Unmarshal(""); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if err := opts.Unmarshal("  ;  ;"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if opts.Len() != 0 {
		t.Errorf("expecting no options, got %d", opts.Len())
	}
}

func TestProviderOptionsUnmarshalInvalid(t *testing.T) {
	opts := NewProviderOptions()
	if err := opts.Unmarshal("gcs.fc_limit"); err == nil {
		t.Fatalf("expecting error, got none")
	}
}

func TestProviderOptionsRoundTrip(t *testing.T) {
	in := "gcs.fc_limit=64;gcs.fc_factor=0.8;evs.keepalive_period=PT1S"
	opts := NewProviderOptions()
	if err := opts.Unmarshal(in); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	out, err := opts.Marshal()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if in != out {
		t.Errorf("expecting round trip %q, got %q", in, out)
	}
}

