func TestProviderOptionsForNode(t *testing.T) {
	tests := []struct {
		name        string
		nodeAddress string
		want        []KVOption
	}{
		{
			name:        "IPv4",
			nodeAddress: "10.0.0.1",
			want: []KVOption{
				NewKVOption(keys.IstRecvAddr, "10.0.0.1:4568"),
			},
		},
		{
			name:        "IPv6",
			nodeAddress: "fd00::1",
			want: []KVOption{
				NewKVOption(keys.IstRecvAddr, "[fd00::1]:4568"),
				NewKVOption(keys.GmcastListenAddr, "tcp://[fd00::1]:4567"),
			},
		},
		{
			name:        "invalid",
			nodeAddress: "invalid",
			want: []KVOption{
				NewKVOption(keys.IstRecvAddr, "invalid:4568"),
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			opts := providerOptionsForNode(tt.nodeAddress)
			for _, want := range tt.want {
				value, ok := opts.Get(want.Key)
				if !ok {
					t.Errorf("expecting option %q to be present", want.Key)
					continue
				}
				if value != want.Value {
					t.Errorf("expecting option %q to be %q, got %q", want.Key, want.Value, value)
				}
			}
			if opts.Len() != len(tt.want) {
				t.Errorf("expecting %d options, got %d", len(tt.want), opts.Len())
			}
		})
	}
}

