func writeTempConfig(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "50-server.cnf")
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		t.Fatalf("error writing config file: %v", err)
	}
	return path
}

func readConfig(t *testing.T, path string) string {
	t.Helper()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("error reading config file: %v", err)
	}
	return string(content)
}

func TestUpdateConfigIPv4(t *testing.T) {
	path := writeTempConfig(t, testConfigContent)
	if err := UpdateConfig(path, "10.0.0.2"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := readConfig(t, path)
	if !strings.Contains(got, "wsrep_node_address=10.0.0.2") {
		t.Errorf("expecting node address to be updated, got:\n%s", got)
	}
	if strings.Contains(got, "wsrep_node_address=10.0.0.1") {
		t.Errorf("expecting old node address to be replaced, got:\n%s", got)
