	}
}

func TestUpdateConfigAppendsMissingKeys(t *testing.T) {
	content := `[mariadb]
wsrep_on=ON
wsrep_provider=/usr/lib/galera/libgalera_smm.so
wsrep_cluster_name=mariadb-galera
wsrep_node_name=mariadb-galera-0
wsrep_sst_method=mariabackup
wsrep_slave_threads=1
`
	path := writeTempConfig(t, content)
	if err := UpdateConfig(path, "10.0.0.1"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := readConfig(t, path)
	if !strings.Contains(got, "wsrep_node_address=10.0.0.1") {
		t.Errorf("expecting node address to be appended, got:\n%s", got)
	}
	if !strings.Contains(got, "wsrep_sst_receive_address=10.0.0.1:4444") {
		t.Errorf("expecting SST receive address to be appended, got:\n%s", got)
	}
	if !strings.Contains(got, "ist.recv_addr=10.0.0.1:4568") {
		t.Errorf("expecting provider options to be appended, got:\n%s", got)
	}
}

func TestUpdateConfigNonExistingFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "non-existing.cnf")
	if err := UpdateConfig(path, "10.0.0.1"); err == nil {
		t.Fatalf("expecting error, got none")
	}
}

func TestUpdateConfigInvalidProviderOptions(t *testing.T) {
	content := `[mariadb]
wsrep_node_address=10.0.0.1
wsrep_provider_options=invalid
`
	path := writeTempConfig(t, content)
	if err := UpdateConfig(path, "10.0.0.2"); err == nil {
		t.Fatalf("expecting error, got none")
	}
}

func TestGetConfigValue(t *testing.T) {
	got := getConfigValue(testConfigContent, "wsrep_node_address")
	if got != "10.0.0.1" {
		t.Errorf("expecting %q, got %q", "10.0.0.1", got)
	}
	got = getConfigValue(testConfigContent, "non-existing")
	if got != "" {
		t.Errorf("expecting empty string, got %q", got)
	}
}

